use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut max_overlap = 0;
    let mut current_overlap = 0;

    for interval in input.as_array() {
        let start = interval[0].as_i64().unwrap();
        let end = interval[1].as_i64().unwrap();

        if start > end {
            // Swap start and end if start is greater than end
            let temp = start;
            start = end;
            end = temp;
        }

        // Update current_overlap
        current_overlap = std::cmp::max(current_overlap, end - start + 1);

        // Update max_overlap if current_overlap is greater
        max_overlap = std::cmp::max(max_overlap, current_overlap);
    }

    serde_json::Value::Number(max_overlap as f64)
}
